using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media.Animation;using System.Windows.Threading;using Rhino;using EP=Eto.Drawing.PointF;
namespace RhinoContextAssist;
public partial class ContextAssistPopup:Window{readonly Action<ContextAction> execute;readonly Action dismiss;readonly ContextAssistSettings settings;readonly DispatcherTimer timer;SelectionContext context=null!;List<ContextAction> all=new();DateTime last;DateTime? hover,leave;bool expanded;
 internal ContextAssistPopup(Action<ContextAction> e,Action d,ContextAssistSettings s){InitializeComponent();execute=e;dismiss=d;settings=s;timer=new DispatcherTimer(TimeSpan.FromMilliseconds(50),DispatcherPriority.Background,(_,_)=>Tick(),Dispatcher);SourceInitialized+=Init;}
 internal void UpdateActions(SelectionContext c,IReadOnlyList<ContextAction>a){context=c;all=a.ToList();Pill.Content=$"{ContextIcon(c.Kind)} {c.Caption} · {a.Count}";TitleText.Text=$"{ContextIcon(c.Kind)} {c.Level}: {c.Caption}";Primary.Children.Clear();var n=Math.Min(settings.PrimaryCount,a.Count);foreach(var x in a.Take(n))Primary.Children.Add(ActionButton(x,false));var more=new Button{Content=$"⋯ Mehr ({Math.Max(0,a.Count-n)})",Style=(Style)FindResource("B")};more.Click+=(_,_)=>{More.IsOpen=!More.IsOpen;SearchBox.Text="";RenderResults(all.Skip(n));};Primary.Children.Add(more);More.PlacementTarget=more;}
 Button ActionButton(ContextAction a,bool list){var fav=settings.IsFavorite(context.Kind,a.Id);var panel=new StackPanel{Orientation=Orientation.Horizontal};panel.Children.Add(new TextBlock{Text=$"{a.Icon} {a.Label}"});var b=new Button{Content=panel,ToolTip=a.Hint+"\nRechtsklick: Favorit",Style=(Style)FindResource(a.Destructive?"Danger":"B"),HorizontalContentAlignment=list?HorizontalAlignment.Left:HorizontalAlignment.Center,MinWidth=list?285:0};b.Click+=(_,_)=>execute(a);b.MouseRightButtonUp+=(_,e)=>{settings.ToggleFavorite(context.Kind,a.Id);e.Handled=true;UpdateActions(context,ActionService.Get(context,settings));};if(fav)b.Content=new TextBlock{Text=$"★ {a.Icon} {a.Label}"};return b;}
 void RenderResults(IEnumerable<ContextAction> items){SearchResults.Children.Clear();foreach(var g in items.GroupBy(x=>x.Category)){SearchResults.Children.Add(new TextBlock{Text=g.Key,Foreground=System.Windows.Media.Brushes.Gray,Margin=new Thickness(6,8,2,2)});foreach(var a in g)SearchResults.Children.Add(ActionButton(a,true));}}
 void SearchBox_TextChanged(object s,TextChangedEventArgs e){var q=SearchBox.Text.Trim();RenderResults(string.IsNullOrEmpty(q)?all.Skip(Math.Min(settings.PrimaryCount,all.Count)):all.Where(x=>(x.Label+" "+x.Hint+" "+x.Category).Contains(q,StringComparison.OrdinalIgnoreCase)));}
 internal void ShowAt(SelectionContext c,PopupPositionMode mode){var p=Position(c,mode);Left=p.X;Top=p.Y;last=DateTime.UtcNow;SetExpanded(settings.UxMode==PopupUxMode.Direct);Opacity=settings.IdleOpacity/100d;Show();Clamp();timer.Start();}
 EP Position(SelectionContext c,PopupPositionMode mode){var v=RhinoDoc.ActiveDoc?.Views.ActiveView;var mouse=Eto.Forms.Mouse.Position;if(v==null)return mouse;var r=v.ScreenRectangle;var p=mouse;if(c.Anchor.IsValid){var q=v.ActiveViewport.WorldToClient(c.Anchor);p=new EP((float)(r.Left+q.X),(float)(r.Top+q.Y));}if(mode==PopupPositionMode.Mouse)return mouse;if(mode==PopupPositionMode.Geometry)return p;if(mode==PopupPositionMode.GeometryOffset)return new(p.X+120,p.Y-80);var m=settings.CornerMarginPx;var pts=new Dictionary<PopupPositionMode,EP>{{PopupPositionMode.TopLeft,new(r.Left+m,r.Top+m)},{PopupPositionMode.TopRight,new(r.Right-m-430,r.Top+m)},{PopupPositionMode.BottomLeft,new(r.Left+m,r.Bottom-m-110)},{PopupPositionMode.BottomRight,new(r.Right-m-430,r.Bottom-m-110)}};return mode==PopupPositionMode.AutoViewportCorner?pts.OrderByDescending(x=>Dist(x.Value,p)).First().Value:pts[mode];}
 static double Dist(EP a,EP b){var x=a.X-b.X;var y=a.Y-b.Y;return x*x+y*y;}void Tick(){if(!IsVisible)return;var now=DateTime.UtcNow;var inside=IsMouseOver||(More.IsOpen&&More.IsMouseOver);if(inside){last=now;leave=null;hover??=now;Fade(settings.ActiveOpacity/100d);if(settings.UxMode==PopupUxMode.Compact&&!expanded&&(now-hover.Value).TotalMilliseconds>=settings.HoverDelayMs)SetExpanded(true);}else{hover=null;Fade(settings.IdleOpacity/100d);if(expanded&&settings.UxMode==PopupUxMode.Compact){leave??=now;var d=More.IsOpen?settings.MoreCollapseDelayMs:settings.CollapseDelayMs;if((now-leave.Value).TotalMilliseconds>=d)SetExpanded(false);}if(settings.AutoHideMs>0&&(now-last).TotalMilliseconds>=settings.AutoHideMs)dismiss();}}
 void SetExpanded(bool x){expanded=x;Pill.Visibility=x?Visibility.Collapsed:Visibility.Visible;Expanded.Visibility=x?Visibility.Visible:Visibility.Collapsed;if(!x)More.IsOpen=false;Dispatcher.BeginInvoke(()=>{UpdateLayout();Clamp();});}void Pill_Click(object s,RoutedEventArgs e)=>SetExpanded(true);void Close_Click(object s,RoutedEventArgs e)=>dismiss();void Fade(double x)=>BeginAnimation(OpacityProperty,new DoubleAnimation(x,TimeSpan.FromMilliseconds(130)));void Clamp(){var w=SystemParameters.WorkArea;Left=Math.Clamp(Left,w.Left+30,Math.Max(w.Left+30,w.Right-ActualWidth-30));Top=Math.Clamp(Top,w.Top+30,Math.Max(w.Top+30,w.Bottom-ActualHeight-30));}void Init(object?s,EventArgs e){var h=new WindowInteropHelper(this).Handle;SetWindowLongPtr(h,-8,RhinoApp.MainWindowHandle());}static string ContextIcon(SelectionKind k)=>k switch{SelectionKind.Block=>"◆",SelectionKind.Mesh or SelectionKind.MeshFace or SelectionKind.MeshEdge=>"△",SelectionKind.Curve or SelectionKind.ClosedPlanarCurve=>"⌁",SelectionKind.SubD or SelectionKind.SubDFace or SelectionKind.SubDEdge=>"◇",_=>"⬒"};[DllImport("user32.dll",EntryPoint="SetWindowLongPtrW")]static extern IntPtr SetWindowLongPtr(IntPtr h,int i,IntPtr n);
